const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const signatureHeader = headers['x-rax-signature'];
const timestampHeader = headers['x-rax-timestamp'];
const rawBodyStr = JSON.stringify(body);

// 1. Verificación de seguridad HMAC
const secret = $env.RAX_N8N_SHARED_SECRET;
if (!secret) { return [{ json: { valid: false, authorized: false, statusCode: 503, error: 'RAX_N8N_SHARED_SECRET is not configured' } }]; }
const hmac = crypto.createHmac('sha256', secret);
const expectedSig = 'sha256=' + hmac.update(`${timestampHeader}.${rawBodyStr}`).digest('hex');

if (signatureHeader !== expectedSig) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: 'Invalid HMAC signature'
    }
  }];
}

// 2. Control de Privacidad Estricto:
// Si el actor es el emprendedor, purgeamos cualquier nota privada de mentor que pudiera haberse filtrado
const actorRole = body.actor?.role;
const context = body.context || {};
let sanitizedNotes = [];
if (actorRole === 'mentor' || actorRole === 'admin') {
  sanitizedNotes = context.mentorNotes || [];
}

// 3. Construir el prompt contextual para OpenRouter (Nivel 2)
const systemPrompt = `Eres el asistente de mentoría de RAX. Tu misión es acompañar al emprendedor con pedagogía socrática.
REGLAS OBLIGATORIAS:
1. Responde en español neutral y profesional.
2. Haz una sola pregunta o reflexión a la vez para no abrumar.
3. Distingue entre hechos registrados, afirmaciones del emprendedor e hipótesis no comprobadas.
4. Si el usuario menciona una duda o falta de información, decláralo como incertidumbre en lugar de adivinar.
5. Si identificas un elemento clave (problema, cliente, métrica), sugiérelo como propuesta con needsHumanApproval: true.
6. Devuelve EXCLUSIVAMENTE un objeto JSON válido con los campos: reply (string), askedDimension (string opcional), proposals (array de propuestas), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  actorRole,
  userMessage: body.message,
  projectName: context.projectName,
  projectSummary: context.projectSummary,
  recentMessages: context.recentMessages || [],
  coveredDimensions: context.coveredDimensions || [],
  pendingDimensions: context.pendingDimensions || [],
  mentorNotesAllowed: sanitizedNotes
});

return [{
  json: {
    valid: true,
    correlationId: body.correlationId,
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Sanitize & Build Chat Prompt').first().json;

let output = null;
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  output = JSON.parse(content);
} catch (e) {
  output = {
    reply: 'He recibido tu mensaje y estoy procesándolo con tu mentor. ¿Podrías brindarme más detalles?',
    uncertainties: ['Salida no estructurada del modelo']
  };
}

return [{
  json: {
    correlationId: prep.correlationId,
    reply: output.reply || 'Entendido. Sigamos profundizando.',
    dimension: output.askedDimension || null,
    proposals: (output.proposals || []).map(p => ({
      ...p,
      needsHumanApproval: true
    })),
    uncertainties: output.uncertainties || [],
    usage: {
      model: response.model || prep.model,
      promptTokens: response.usage?.prompt_tokens || 0,
      completionTokens: response.usage?.completion_tokens || 0
    }
  }
}];
